\label{thmA}
For all $1\le m<n$ there is an isomorphism of varieties $U_{m,n}\cong\operatorname{GL}_m(\mathbb{C})\times Y_{m,n}$ with $Y_{m,n}\cong\operatorname{Gr}(m,n)^\circ\cong\operatorname{Gr}(n-m,n)^\circ\cong Y_{n-m,n}$. If $m\in\{2,n-2\}$, then
\[U_{m,n}\;\cong\;\operatorname{GL}_m(\mathbb{C})\times(\mathbb{C}^*)^{n-1}\times\mathcal{M}_{0}{}_{,n}.\]
In particular,
\begin{gather*}
U_{3,5}\cong\operatorname{GL}_3(\mathbb{C})\times(\mathbb{C}^*)^4\times\mathcal{M}_{0}{}_{,5}\simeq\operatorname{SU}(3)\times T^5\times\mathcal{M}_{0}{}_{,5},\\
\operatorname{Poin}(U_{3,5},t)=(1+t)^5(1+t^3)(1+t^5)(1+2t)(1+3t)=(1+t^5) \cdot \operatorname{Poin}(U_{2,5},t),\\
\pi_i(U_{3,5})\cong\pi_i(\operatorname{SU}(3)) \text{ for } i\ge2 \text{ and } \pi_1(U_{3,5})\cong\mathbb{Z}^4\times \mathfrak{P}_4.
\end{gather*}

\label{thmB}
The divisor $D_{3,5}\subset\mathbb{C}^{15}$ is not free. More precisely, let $R=\mathbb{C}[x_{rk}]$, then
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2em]
\item $\operatorname{Der}(-\log D_{3,5})$ is minimally generated by the $13$ linear vector fields coming from the action of $\operatorname{GL}_3\times(\mathbb{C}^*)^5$ and by five vector fields $\Phi_1,\dots,\Phi_5$ of degree $10$, given explicitly in \eqref{eq:psi} and Definition~\ref{def:Phi};
\item its minimal graded free resolution is
\[0\longrightarrow R(-11)^3\longrightarrow R(-1)^{13}\oplus R(-10)^5\longrightarrow\operatorname{Der}(-\log D_{3,5})\longrightarrow 0,\]
and the three syzygies are of the form $\sum_{k=1}^5x_{rk}\Phi_k\in R\cdot\mathcal{L}$, $r=1,2,3$, where $\mathcal{L}$ is the space of linear logarithmic fields. Hence $\operatorname{Der}(-\log D_{3,5})/R\mathcal{L}\cong\operatorname{coker}\big(M^T\colon R(-11)^3\to R(-10)^5\big)$;
\item the stalk of $\operatorname{Der}(-\log D_{3,5})$ at a point $p$ needs exactly $18-\operatorname{rk} M(p)$ generators. In particular the non-free locus of $D_{3,5}$ is the determinantal variety $\{\operatorname{rk} M\le 2\}$, of codimension $3$.
\end{enumerate}

\label{thmC}
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2em]
\item At a point of rank $m$, the germ of $D_{m,n}$ is isomorphic, up to a smooth factor, to the germ of $D_{n-m,n}$ at a point of rank $n-m$. Consequently $D_{n-2,n}$ is free at all points of rank $n-2$; in particular $D_{3,5}$ is free at all matrices of rank $3$.
\item Near a rank-two matrix whose columns are pairwise independent, $D_{3,5}$ is (up to a smooth factor) a two-parameter family of central arrangements $\mathcal{A}(P_1,\dots,P_5)\subset\mathbb{C}^3$ of the ten planes $\operatorname{span}(P_i,P_j)$, where $P_1,\dots,P_5\in\mathbb{C}^3$ are in general position and are the Gale transform of the five columns; the minor $\Delta_I$ corresponds to the plane spanned by $P_j,P_k$ with $\{j,k\}=[5]\setminus I$.
\item Each arrangement $\mathcal{A}(P_1,\dots,P_5)$ has characteristic polynomial $(t-1)(t^2-9t+21)$ and is therefore not free.
\end{enumerate}

\label{prop:gale}
\begin{enumerate}[label=\textup{(\alph*)},leftmargin=2em]
\item Transposition $W\mapsto W^T$ maps $E_{m,n}$ isomorphically onto $E_{n-m,n}$ and $Y_{m,n}$ onto $Y_{n-m,n}$.
\item The map $W\mapsto\operatorname{rowspace}[I_m|W]$ is an isomorphism of $Y_{m,n}$ onto the open subset $\operatorname{Gr}(m,n)^\circ\subset\operatorname{Gr}(m,n)$ where all Pl\"ucker coordinates are nonzero.
\item Under \textup{(b)}, the isomorphism $W\mapsto-W^T$ \textup{(}the composite of \textup{(a)} with $W\mapsto -W$\textup{)} corresponds to $\Lambda\mapsto\Lambda^\perp$, followed by the cyclic renumbering of the coordinates that puts the last $n-m$ first. This is the classical association, or Gale transform, of point configurations \cite{DO,GGMS}.
\end{enumerate}

\label{thm:complement}
For $1\le m<n$ one has:
\begin{enumerate}[label=\textup{(\alph*)},leftmargin=2em]
\item $U_{m,n}\cong\operatorname{GL}_m(\mathbb{C})\times Y_{m,n}$ and $Y_{m,n}\cong\operatorname{Gr}(m,n)^\circ\cong\operatorname{Gr}(n-m,n)^\circ\cong Y_{n-m,n}$;
\item $\operatorname{Poin}(U_{m,n},t)=\prod_{k=1}^m(1+t^{2k-1})\cdot\operatorname{Poin}(Y_{m,n},t)$. In particular,
\[\frac{\operatorname{Poin}(U_{m,n},t)}{\operatorname{Poin}(\operatorname{GL}_m,t)}=\frac{\operatorname{Poin}(U_{n-m,n},t)}{\operatorname{Poin}(\operatorname{GL}_{n-m},t)};\]
\item $U_{m,n}\simeq\operatorname{SU}(m)\times S^1\times Y_{m,n}$. Hence $\pi_i(U_{m,n})\cong\pi_i(\operatorname{SU}(m))\oplus\pi_i(Y_{m,n})$ for $i\ge2$ and $\pi_1(U_{m,n})\cong\mathbb{Z}\times\pi_1(Y_{m,n})$.
\end{enumerate}

\label{cor:nminus2}
Let $n\ge4$ and $m\in\{2,n-2\}$. Then $U_{m,n}\cong\operatorname{GL}_m(\mathbb{C})\times(\mathbb{C}^*)^{n-1}\times\mathcal{M}_{0}{}_{,n}$, and
\begin{enumerate}[label=\textup{(\alph*)},leftmargin=2em]
\item $\displaystyle\operatorname{Poin}(U_{m,n},t)=\prod_{k=1}^m(1+t^{2k-1})\cdot(1+t)^{n-1}\cdot\prod_{k=2}^{n-2}(1+kt)$;
\item $\pi_i(U_{m,n})\cong\pi_i(\operatorname{SU}(m))$ for $i\ge2$; the universal cover of $U_{m,n}$ is homotopy equivalent to $\operatorname{SU}(m)$;
\item $\pi_1(U_{m,n})\cong\mathbb{Z}^{n}\times\pi_1(\mathcal{M}_{0}{}_{,n})\cong\mathbb{Z}^{n-1}\times \mathfrak{P}_{n-1}$;
\item $|U_{m,n}(\mathbb{F}_q)|=|\operatorname{GL}_m(\mathbb{F}_q)|\,(q-1)^{n-1}\prod_{k=2}^{n-2}(q-k)$.
\end{enumerate}

\label{cor:35top}
$U_{3,5}\cong\operatorname{GL}_3(\mathbb{C})\times(\mathbb{C}^*)^4\times\mathcal{M}_{0}{}_{,5}\simeq\operatorname{SU}(3)\times T^5\times\mathcal{M}_{0}{}_{,5}$, and
\begin{align*}
\operatorname{Poin}(U_{3,5},t)&=(1+t)^5(1+t^3)(1+t^5)(1+2t)(1+3t)=(1+t^5)\,\operatorname{Poin}(U_{2,5},t)\\
&=1+10t+41t^2+91t^3+125t^4+128t^5+135t^6+162t^7+177t^8+160t^9\\
&\quad+133t^{10}+125t^{11}+121t^{12}+86t^{13}+35t^{14}+6t^{15}.
\end{align*}
Furthermore $\pi_i(U_{3,5})\cong\pi_i(\operatorname{SU}(3))$ for $i\ge2$ \textup{(}so $\pi_2=\pi_4=0$, $\pi_3\cong\pi_5\cong\mathbb{Z}$, $\pi_6\cong\mathbb{Z}/6$, \dots\textup{)}, $\pi_1(U_{3,5})\cong\mathbb{Z}^4\times \mathfrak{P}_4$ and $\chi(U_{3,5})=0$.

\label{prop:tenplanes}
Let $P_1,\dots,P_5$ be vectors in $K^3$, $K$ is a field, any three of which are linearly independent. Let $\mathcal{A}=\mathcal{A}(P_1,\dots,P_5)$ be the central arrangement of the ten planes $H_{ij}=\operatorname{span}(P_i,P_j)$, $1\le i<j\le5$. Then
\begin{enumerate}[label=\textup{(\alph*)},leftmargin=2em]
\item the planes $H_{ij}$ are pairwise distinct;
\item the rank-two flats of $\mathcal{A}$ are the five lines $KP_i$, each contained in exactly the four planes $H_{ij}$ \textup{(}$j\ne i$\textup{)}, and the fifteen lines $H_{ij}\cap H_{kl}$ with $\{i,j\}\cap\{k,l\}=\emptyset$, each contained in exactly two planes;
\item $\chi_\mathcal{A}(t)=t^3-10t^2+30t-21=(t-1)(t^2-9t+21)$, and for $K=\mathbb{C}$, $\operatorname{Poin}(M(\mathcal{A}),t)=(1+t)(1+9t+21t^2)$;
\item $\mathcal{A}$ is not free.
\end{enumerate}

\label{cor:fullrankfree}
\begin{enumerate}[label=\textup{(\alph*)},leftmargin=2em]
\item $D_{n-1,n}$ is free at all points of rank $n-1$, being locally a normal crossing divisor there \textup{(}Gale dual to $D_{1,n}$\textup{)}.
\item $D_{n-2,n}$ is free at all points of rank $n-2$, because $D_{2,n}$ is free \cite[Theorem~3.3]{Yim} -- see also Appendix~\ref{app:2n}. In particular, $D_{3,5}$ is free at every matrix of rank $3$, and $D_{4,6}$ at every matrix of rank $4$.
\end{enumerate}

\label{prop:certificate}
Let $S=\mathbb{C}[a_3,a_4,a_5,b_3,b_4,b_5,c_3,c_4,c_5]$ and let $f'=f'_{3,5}\in S$ be as in Example~\ref{ex:chart35}. Then:
\begin{enumerate}[label=\textup{(\alph*)},leftmargin=2em]
\item $\operatorname{Der}(-\log f')$ has minimal free resolution $0\to S(-7)\to S(-1)^7\oplus S(-6)^3\to\operatorname{Der}(-\log f')\to0$, with the seven linear generators listed in Example~\ref{ex:chart35};
\item the non-free locus of $E'_{3,5}=V(f')$ is the linear subspace $\{c=0\}$.
\end{enumerate}
